model.component("comp1").physics().create("spf", "TurbulentFlowAlgebraicYplus", "geom1");
model.study().create("std1");
model.study("std1").create("wdi", "WallDistanceInitialization");
model.study("std1").create("stat", "Stationary");
// Application Library: Mixer_Module/Applications/mixer uses this model for the stirred-tank app

model.component("comp1").physics().create("spf", "TurbulentFlowv2f", "geom1");
model.study().create("std1");
model.study("std1").create("wdi", "WallDistanceInitialization");
model.study("std1").create("stat", "Stationary");
// Application Library: CFD_Module/Single-Phase_Flow/hydrocyclone

model.component("comp1").physics().create("spf", "TurbulentFlowSSGLRR", "geom1");
model.study().create("std1");
model.study("std1").create("wdi", "WallDistanceInitialization");
model.study("std1").create("stat", "Stationary");
// Application Library: CFD_Module/Single-Phase_Flow/semicircular_duct and rotating_pipe_swirling_jet

model.component("comp1").physics().create("spf", "LESRBVM", "geom1");
model.study().create("std1");
model.study("std1").create("time", "Transient");
// Application Library: CFD_Module/Single-Phase_Flow/les_3d_hill (initialized with Incompressible Potential Flow) and sports_car

model.component("comp1").physics().create("spf", "LaminarFlow", "geom1");
// convert the laminar interface to SST with low-Re wall treatment
model.component("comp1").physics("spf").prop("TurbulenceModelProperty").set("TurbulenceModelType", "RANS");
model.component("comp1").physics("spf").prop("TurbulenceModelProperty").set("TurbulenceModel", "SST");
model.component("comp1").physics("spf").prop("TurbulenceModelProperty").set("WallTreatment", "LowReynoldsNumber");

model.component("comp1").physics().create("spf", "TurbulentFlowkeps", "geom1");
model.component("comp1").physics("spf").create("nturb1", "NewTurbulenceModel", -1);
// GUI: select Turbulent Flow, SST in nturb1 and click Create
// Application Library: Mixer_Module/Tutorials/modular_mixer_kw, CFD_Module/Verification_Examples/fda_benchmark_blood_pump

model.component("comp1").physics().create("hmnf", "HighMachNumberFlowTurbulentSpalartAllmaras", "geom1");
model.study().create("std1");
model.study("std1").create("wdi", "WallDistanceInitialization");
model.study("std1").create("stat", "Stationary");
